  it('rejects input missing a required property returning a ToolResponse and not calling the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      mentionsLocation: response.result.includes('location'),
      mentionsRequired: /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      mentionsLocation: true,
      mentionsRequired: true,
    });
  });
});

